"""Part factories for the clockwork wooden ox. Every factory returns geometry
already placed in the ox frame (see params.py)."""

from __future__ import annotations

import math

from cadgen import build123d as bd

from lib.gears import gear_disc, ratchet_outline
from lib.params import (
    ARBOR_CORE_D, ARBOR_Y_LEFT, AXLE_Z, BARREL_FLOOR, BARREL_OD, BARREL_TEETH,
    BARREL_WALL, BARREL_Y0, BOTTOM_Z0, BOX_PLY, BUSHING_OD, CAP_T, CAVITY_Y0,
    CAVITY_Y1, CRANK_PINION_TEETH, CRANK_R, CRANK_Y0, CRANK_Y1, DECK_HALF_W,
    DECK_X0, DECK_X1, END_X0, END_X1, FAN_GEAR_Y0, FAN_GEAR_Y1, FAN_PINION_TEETH,
    FAN_R, FAN_SHAFT_D, FAN_WHEEL_TEETH, FAN_X, FAN_Z, GEAR_Y0, GEAR_Y1, GUIDE_D,
    GUIDE_Z, HIP_X, HOOF_H, KEY_SQUARE, LEG_LEN, LEG_Y0, LEG_Y1, M_FAN, M_MAIN,
    PAD_T, PLATE_IN, PLATE_OUT, PLATE_X, PLATE_Z0, PLATE_Z1, PLY, RATCHET_R,
    RATCHET_TEETH, RATCHET_Y0, RATCHET_Y1, SHAFT_D, SLOT_W, SPRING_T, SPRING_W,
    leg_pose,
)

# Pivot of the ratchet click (pawl) on the left plate, and its tip on the ratchet.
CLICK_PIVOT = (17.0, AXLE_Z + 12.0)
CLICK_TIP_ANGLE = 45.0
HOOF_R = 20.0          # radius of the rocking hoof sole (axis along Y)


# --------------------------------------------------------------------------
# Placement helpers
# --------------------------------------------------------------------------
def axial(shape: bd.Shape, x: float, z: float, spin_deg: float = 0.0) -> bd.Shape:
    """Place a part modelled about local +Z on a world axis parallel to +Y.

    Local z becomes world y; local angle b lands at world XZ angle -b.
    """
    return bd.Pos(x, 0, z) * bd.Rot(-90, 0, 0) * bd.Rot(0, 0, spin_deg) * shape


def cyl(r: float, z0: float, z1: float) -> bd.Part:
    return bd.Pos(0, 0, z0) * bd.Cylinder(r, z1 - z0, align=(bd.Align.CENTER, bd.Align.CENTER, bd.Align.MIN))


def xz_slab(face: bd.Face | bd.Sketch, y0: float, y1: float) -> bd.Part:
    """Extrude a profile drawn in local XY as (x, z) into world y0..y1."""
    return bd.Pos(0, y1, 0) * bd.Rot(90, 0, 0) * bd.extrude(face, amount=y1 - y0)


def rect(x0: float, x1: float, z0: float, z1: float) -> bd.Sketch:
    return bd.Pos((x0 + x1) / 2, (z0 + z1) / 2) * bd.Rectangle(x1 - x0, z1 - z0)


def circle(x: float, z: float, d: float) -> bd.Sketch:
    return bd.Pos(x, z) * bd.Circle(d / 2)


def box(x0, x1, y0, y1, z0, z1) -> bd.Part:
    return bd.Pos((x0 + x1) / 2, (y0 + y1) / 2, (z0 + z1) / 2) * bd.Box(x1 - x0, y1 - y0, z1 - z0)


def side_y(y0: float, y1: float, left: bool) -> tuple[float, float]:
    return (y0, y1) if left else (-y1, -y0)


# --------------------------------------------------------------------------
# Plywood frame (laser cut, 6 mm birch ply, tab-and-slot, glued)
# --------------------------------------------------------------------------
END_TABS_Z = ((34.0, 50.0), (74.0, 90.0))
BOTTOM_TABS_X = ((-40.0, -20.0), (20.0, 40.0))
DECK_SCREWS = [(sx * (END_X0 + END_X1) / 2, sy * 8.0) for sx in (1, -1) for sy in (1, -1)]
BUSHING_XZ = [(HIP_X, AXLE_Z), (-HIP_X, AXLE_Z), (0.0, AXLE_Z), (FAN_X, FAN_Z)]


def side_plate(left: bool) -> bd.Part:
    outline = rect(-PLATE_X, PLATE_X, PLATE_Z0, PLATE_Z1)
    outline = bd.fillet(outline.vertices(), 8.0)
    cut = [circle(x, z, BUSHING_OD) for x, z in BUSHING_XZ]
    cut += [circle(sx * HIP_X, GUIDE_Z, 4.6) for sx in (1, -1)]            # threaded inserts
    for sx in (1, -1):                                                     # end-plate tab slots
        x0, x1 = sorted((sx * END_X0, sx * END_X1))
        cut += [rect(x0, x1, z0, z1) for z0, z1 in END_TABS_Z]
    cut += [rect(x0, x1, BOTTOM_Z0, BOTTOM_Z0 + PLY) for x0, x1 in BOTTOM_TABS_X]
    if left:
        cut.append(circle(*CLICK_PIVOT, 2.1))
        cut.append(circle(24.0, AXLE_Z + 4.0, 2.1))                       # click spring post
    face = outline
    for c in cut:
        face -= c
    return xz_slab(face, *side_y(PLATE_IN, PLATE_OUT, left))


def end_plate(front: bool) -> bd.Part:
    """Front or rear plate between the side plates, with through-tabs."""
    s = 1 if front else -1
    x0, x1 = sorted((s * END_X0, s * END_X1))
    body = box(x0, x1, -PLATE_IN, PLATE_IN, BOTTOM_Z0 + PLY, PLATE_Z1)
    for z0, z1 in END_TABS_Z:
        body += box(x0, x1, -PLATE_OUT, PLATE_OUT, z0, z1)
    if front:
        body -= box(x0 - 1, x1 + 1, -5.1, 5.1, 89.9, 100.1)                # neck tenon mortise
    else:
        body -= bd.Pos(x0 - 1, 0, 96) * bd.Rot(0, 90, 0) * cyl(2.15, 0, PLY + 2)  # tail hole
    return body


def bottom_plate() -> bd.Part:
    body = box(-60, 60, -PLATE_IN, PLATE_IN, BOTTOM_Z0, BOTTOM_Z0 + PLY)
    for x0, x1 in BOTTOM_TABS_X:
        body += box(x0, x1, -PLATE_OUT, PLATE_OUT, BOTTOM_Z0, BOTTOM_Z0 + PLY)
    return body


def deck() -> bd.Part:
    plate = box(DECK_X0, DECK_X1, -DECK_HALF_W, DECK_HALF_W, PLATE_Z1, PLATE_Z1 + PLY)
    plate = plate.fillet(2.0, plate.edges().filter_by(bd.Axis.Z))
    for x, y in DECK_SCREWS:
        plate -= bd.Pos(x, y, PLATE_Z1 - 1) * cyl(1.4, 0, PLY + 2)
    return plate


def deck_screw(x: float, y: float) -> bd.Part:
    """M2.5 x 16 pan-head wood screw into the end-plate top edge."""
    return bd.Pos(x, y, 0) * (cyl(1.25, PLATE_Z1 - 10, PLATE_Z1 + PLY) + cyl(2.3, PLATE_Z1 + PLY, PLATE_Z1 + PLY + 1.8))


def bushing(x: float, z: float, left: bool, bore: float) -> bd.Part:
    y0, y1 = side_y(PLATE_IN, PLATE_OUT, left)
    return axial(cyl(BUSHING_OD / 2, y0, y1) - cyl(bore / 2, y0 - 1, y1 + 1), x, z)


# --------------------------------------------------------------------------
# Going barrel, arbor, ratchet, key
# --------------------------------------------------------------------------
def barrel() -> bd.Part:
    """Drum with integral 72T m1 gear (one SLA/FDM print or turned brass)."""
    top = CAVITY_Y1
    drum = cyl(BARREL_OD / 2, BARREL_Y0, top) - cyl(BARREL_OD / 2 - BARREL_WALL, CAVITY_Y0, top + 1)
    drum -= cyl(SHAFT_D / 2 + 0.15, BARREL_Y0 - 1, top)
    gear = bd.Pos(0, 0, GEAR_Y0) * gear_disc(M_MAIN, BARREL_TEETH, GEAR_Y1 - GEAR_Y0, 0)
    gear -= cyl(BARREL_OD / 2 - 0.5, GEAR_Y0 - 1, GEAR_Y1 + 1)
    for i in range(6):
        a = math.radians(30 + 60 * i)
        gear -= bd.Pos(24.5 * math.cos(a), 24.5 * math.sin(a), 0) * cyl(5.0, GEAR_Y0 - 1, GEAR_Y1 + 1)
    return axial(drum + gear, 0, AXLE_Z)


def barrel_cap() -> bd.Part:
    y0 = CAVITY_Y1
    cap = cyl(BARREL_OD / 2, y0, y0 + CAP_T) + cyl(BARREL_OD / 2 - BARREL_WALL - 0.1, y0 - 1.0, y0)
    cap -= cyl(SHAFT_D / 2 + 0.15, y0 - 2, y0 + CAP_T + 1)
    return axial(cap, 0, AXLE_Z)


def mainspring() -> bd.Part:
    """Let-down 6 x 0.25 mm spring-steel strip, inner eye on the arbor core."""
    r0, r1, turns = ARBOR_CORE_D / 2 + 0.3, BARREL_OD / 2 - BARREL_WALL - 0.4, 6
    n = 72 * turns
    outer, inner = [], []
    for i in range(n + 1):
        a = 2 * math.pi * turns * i / n
        r = r0 + (r1 - r0 - SPRING_T) * i / n
        outer.append(((r + SPRING_T) * math.cos(a), (r + SPRING_T) * math.sin(a)))
        inner.append((r * math.cos(a), r * math.sin(a)))
    face = bd.make_face(bd.Polyline(*(outer + inner[::-1]), close=True))
    z0 = CAVITY_Y0 + 0.5
    return axial(bd.Pos(0, 0, z0) * bd.extrude(face, amount=SPRING_W), 0, AXLE_Z)


def arbor() -> bd.Part:
    """Turned silver-steel arbor: core for the spring eye, square winding end."""
    a = cyl(SHAFT_D / 2, -PLATE_OUT, ARBOR_Y_LEFT - 10)
    a += cyl(ARBOR_CORE_D / 2, CAVITY_Y0 + 0.2, CAVITY_Y1 - 0.2)
    a += bd.Pos(0, 0, (ARBOR_Y_LEFT - 10 + ARBOR_Y_LEFT) / 2) * bd.Box(KEY_SQUARE, KEY_SQUARE, 10)
    return axial(a, 0, AXLE_Z)


def ratchet() -> bd.Part:
    face = bd.make_face(bd.Polyline(*ratchet_outline(RATCHET_R, RATCHET_TEETH, 1.6), close=True))
    r = bd.Pos(0, 0, RATCHET_Y0) * bd.extrude(face, amount=RATCHET_Y1 - RATCHET_Y0)
    r += cyl(4.0, RATCHET_Y1, RATCHET_Y1 + 1.5)                           # pinned hub
    r -= cyl(SHAFT_D / 2, RATCHET_Y0 - 1, RATCHET_Y1 + 3)
    return axial(r, 0, AXLE_Z)


def arbor_collar() -> bd.Part:
    return axial(cyl(4.0, -14.0, -10.0) - cyl(SHAFT_D / 2, -15, -9), 0, AXLE_Z)


def click() -> bd.Part:
    """Ratchet pawl pivoting on an M2 screw in the left plate."""
    px, pz = CLICK_PIVOT
    a = math.radians(CLICK_TIP_ANGLE)
    tx, tz = (RATCHET_R - 1.0) * math.cos(a), AXLE_Z + (RATCHET_R - 1.0) * math.sin(a)
    body = bd.make_hull((circle(px, pz, 6.0) + circle(tx, tz, 1.6)).edges())
    pawl = xz_slab(body - circle(px, pz, 2.1), RATCHET_Y0, RATCHET_Y1)
    return pawl


def click_screw() -> bd.Part:
    px, pz = CLICK_PIVOT
    return axial(cyl(1.0, RATCHET_Y0 - 0.5, PLATE_OUT) + cyl(2.0, PLATE_OUT, PLATE_OUT + 1.4), px, pz)


def click_spring() -> bd.Part:
    """0.6 mm music-wire spring from its post, pressing the pawl onto the ratchet."""
    post = axial(cyl(1.0, RATCHET_Y0 + 1.0, PLATE_OUT) + cyl(2.0, PLATE_OUT, PLATE_OUT + 1.4), 24.0, AXLE_Z + 4.0)
    path = bd.Spline((24.0, (RATCHET_Y0 + RATCHET_Y1) / 2, AXLE_Z + 4.0),
                     (19.0, (RATCHET_Y0 + RATCHET_Y1) / 2, AXLE_Z + 4.6),
                     (13.5, (RATCHET_Y0 + RATCHET_Y1) / 2, AXLE_Z + 7.2))
    wire = bd.sweep(path.location_at(0) * bd.Circle(0.3), path)
    return post + wire


def winding_key() -> bd.Part:
    """Butterfly key; its square socket slips over the arbor end."""
    hub = cyl(4.5, ARBOR_Y_LEFT - 9, ARBOR_Y_LEFT + 1) - bd.Pos(0, 0, ARBOR_Y_LEFT - 4.5) * bd.Box(KEY_SQUARE + 0.2, KEY_SQUARE + 0.2, 9.2)
    wing = bd.make_hull((circle(-11, 0, 12) + circle(11, 0, 12)).edges())
    wing = bd.Pos(0, 0, ARBOR_Y_LEFT + 1) * bd.extrude(wing, amount=3.0)
    return axial(hub + wing, 0, AXLE_Z)


# --------------------------------------------------------------------------
# Crankshafts, crank discs, gears, governor
# --------------------------------------------------------------------------
def crankshaft(x: float) -> bd.Part:
    return axial(cyl(SHAFT_D / 2, -CRANK_Y1, CRANK_Y1), x, AXLE_Z)


def crank_pinion(x: float) -> bd.Part:
    g = bd.Pos(0, 0, GEAR_Y0) * gear_disc(M_MAIN, CRANK_PINION_TEETH, GEAR_Y1 - GEAR_Y0, 0)
    g += cyl(4.5, GEAR_Y1, GEAR_Y1 + 5)
    g -= cyl(SHAFT_D / 2, GEAR_Y0 - 1, GEAR_Y1 + 6)
    g -= bd.Pos(0, 0, GEAR_Y1 + 2.5) * bd.Rot(0, 90, 0) * cyl(1.25, 0, 6)      # M3 grub
    # 180/18 = 10 deg: a tooth space faces the barrel gear on either side
    return axial(g, x, AXLE_Z, 10.0)


def fan_wheel() -> bd.Part:
    g = bd.Pos(0, 0, FAN_GEAR_Y0) * gear_disc(M_FAN, FAN_WHEEL_TEETH, FAN_GEAR_Y1 - FAN_GEAR_Y0, 0)
    for i in range(5):
        a = math.radians(36 + 72 * i)
        g -= bd.Pos(12 * math.cos(a), 12 * math.sin(a), 0) * cyl(3.2, FAN_GEAR_Y0 - 1, FAN_GEAR_Y1 + 1)
    g += cyl(4.5, FAN_GEAR_Y1, FAN_GEAR_Y1 + 4)
    g -= cyl(SHAFT_D / 2, FAN_GEAR_Y0 - 1, FAN_GEAR_Y1 + 5)
    return axial(g, HIP_X, AXLE_Z, -70.0)


def fan_pinion() -> bd.Part:
    g = bd.Pos(0, 0, FAN_GEAR_Y0) * gear_disc(M_FAN, FAN_PINION_TEETH, FAN_GEAR_Y1 - FAN_GEAR_Y0, FAN_SHAFT_D)
    return axial(g, FAN_X, FAN_Z, 128.0)


def fan_shaft() -> bd.Part:
    return axial(cyl(FAN_SHAFT_D / 2, -PLATE_OUT, PLATE_OUT), FAN_X, FAN_Z)


def fan() -> bd.Part:
    """Air-brake governor: four 0.8 mm vanes on a hub, spun 18x barrel speed."""
    f = cyl(3.0, -10.0, 3.0)
    for a in (0, 90):
        f += bd.Rot(0, 0, a) * box(-FAN_R, FAN_R, -0.4, 0.4, -10.0, 2.0)
    f -= cyl(FAN_SHAFT_D / 2, -11, 4)
    return axial(f, FAN_X, FAN_Z)


def crank_disc(x: float, left: bool, theta_deg: float) -> bd.Part:
    """Crank disc pinned to the shaft end (M3 grub); crank pin at CRANK_R."""
    y0, y1 = side_y(CRANK_Y0, CRANK_Y1, left)
    d = cyl(CRANK_R + 5.0, y0, y1) - cyl(SHAFT_D / 2, y0 - 1, y1 + 1)
    d -= bd.Pos(CRANK_R, 0, 0) * cyl(1.25, y0 - 1, y1 + 1)               # M3 tapped
    d -= bd.Pos(0, 0, (y0 + y1) / 2) * bd.Rot(0, 90, 0) * bd.Rot(0, 0, 0) * bd.Pos(0, 0, -CRANK_R - 6) * cyl(1.25, 0, CRANK_R)  # grub
    return axial(d, x, AXLE_Z, -theta_deg)


def crank_pin(x: float, left: bool, theta_deg: float) -> bd.Part:
    """M3 shoulder screw: Ø4 shoulder through the leg's top hole."""
    t = math.radians(theta_deg)
    px, pz = x + CRANK_R * math.cos(t), AXLE_Z + CRANK_R * math.sin(t)
    if left:
        p = cyl(1.5, CRANK_Y0 + 0.5, CRANK_Y1) + cyl(2.0, CRANK_Y1, LEG_Y1 + 0.3) + cyl(3.5, LEG_Y1 + 0.3, LEG_Y1 + 2.3)
    else:
        p = cyl(1.5, -CRANK_Y1, -CRANK_Y0 - 0.5) + cyl(2.0, -LEG_Y1 - 0.3, -CRANK_Y1) + cyl(3.5, -LEG_Y1 - 2.3, -LEG_Y1 - 0.3)
    return axial(p, px, pz)


def guide_insert(x: float, left: bool) -> bd.Part:
    y0, y1 = side_y(PLATE_IN, PLATE_OUT, left)
    return axial(cyl(2.3, y0, y1) - cyl(1.5, y0 - 1, y1 + 1), x, GUIDE_Z)


def guide_spacer(x: float, left: bool) -> bd.Part:
    y0, y1 = side_y(PLATE_OUT, LEG_Y0 - 0.2, left)
    return axial(cyl(4.0, y0, y1) - cyl(2.1, y0 - 1, y1 + 1), x, GUIDE_Z)


def guide_bolt(x: float, left: bool) -> bd.Part:
    """M3 shoulder bolt (Ø4 shoulder) the leg slot slides and swings on."""
    s = 1 if left else -1
    def yr(a, b):
        return tuple(sorted((s * a, s * b)))
    b = cyl(1.5, *yr(PLATE_IN + 0.5, LEG_Y0 - 0.2))
    b += cyl(GUIDE_D / 2, *yr(LEG_Y0 - 0.2, LEG_Y1 + 0.3))
    b += cyl(3.5, *yr(LEG_Y1 + 0.3, LEG_Y1 + 3.0))
    return axial(b, x, GUIDE_Z)


# --------------------------------------------------------------------------
# Legs (5 mm ply), hooves (carved/printed), rubber pads
# --------------------------------------------------------------------------
LEG_END = -(LEG_LEN - PAD_T - HOOF_H) - 6.0     # leg tenon depth 6 into the hoof
SLOT_NEAR, SLOT_FAR = 19.0, 33.0               # guide distance range from the pin


def _leg_local() -> bd.Part:
    """Leg in its own frame: pin at origin, leg along local -Z, thickness in Y."""
    top = circle(0, 0, 16.0)
    taper = bd.Polygon((-8, 0), (8, 0), (5.5, -44), (5.5, LEG_END), (-5.5, LEG_END), (-5.5, -44))
    face = top + taper
    face -= circle(0, 0, 4.2)
    face -= bd.Pos(0, -(SLOT_NEAR + SLOT_FAR) / 2) * bd.SlotCenterToCenter(SLOT_FAR - SLOT_NEAR, SLOT_W, rotation=90)
    face = face.fillet(face.vertices().filter_by(lambda v: v.Y < -40), 0.8) if False else face
    return xz_slab(face, -2.5, 2.5)


def _hoof_local() -> bd.Part:
    z_top = -(LEG_LEN - PAD_T - HOOF_H)
    z_sole = -(LEG_LEN - PAD_T)
    blk = box(-8, 8, -6, 6, z_sole - 2, z_top)
    sole = bd.Pos(0, 0, z_sole + HOOF_R) * bd.Rot(90, 0, 0) * bd.Cylinder(HOOF_R, 12.0)
    h = blk & sole
    h = h.fillet(1.5, h.edges().filter_by(bd.Axis.Z))
    h -= box(-5.6, 5.6, -2.6, 2.6, z_top - 6.0, z_top + 1)                 # leg socket
    h -= box(5.0, 9, -0.6, 0.6, z_sole - 3, z_sole + 3.0)                  # cloven toe
    return h


def _pad_local() -> bd.Part:
    z_sole = -(LEG_LEN - PAD_T)
    c = bd.Pos(0, 0, z_sole + HOOF_R) * bd.Rot(90, 0, 0)
    shell = c * bd.Cylinder(HOOF_R + PAD_T, 11.0) - c * bd.Cylinder(HOOF_R, 12.0)
    return shell & box(-7.5, 7.5, -5.5, 5.5, -LEG_LEN - 1, z_sole + 4.0)


def leg_place(shape: bd.Shape, hip_x: float, left: bool, theta_deg: float) -> bd.Shape:
    px, pz, ang = leg_pose(theta_deg, hip_x)
    beta = ang + 90.0
    yc = (LEG_Y0 + LEG_Y1) / 2 * (1 if left else -1)
    return bd.Pos(px, yc, pz) * bd.Rot(0, -beta, 0) * shape


def leg(hip_x, left, theta):
    return leg_place(_leg_local(), hip_x, left, theta)


def hoof(hip_x, left, theta):
    return leg_place(_hoof_local(), hip_x, left, theta)


def pad(hip_x, left, theta):
    return leg_place(_pad_local(), hip_x, left, theta)


# --------------------------------------------------------------------------
# Ox shell: head, horns, eyes, tail, cargo box
# --------------------------------------------------------------------------
HEAD_LOC = (102.0, 0.0, 110.0)
HEAD_PITCH = 15.0      # nose down


def _head_frame(shape):
    return bd.Pos(*HEAD_LOC) * bd.Rot(0, HEAD_PITCH, 0) * shape


def head() -> bd.Part:
    """Carved basswood (or printed) head with neck and the tenon that locks
    into the front plate."""
    h = bd.Box(30, 26, 24)
    h = h.fillet(4.0, h.edges())
    snout = bd.Pos(16, 0, -5) * bd.Box(14, 22, 16)
    snout = snout.fillet(4.5, snout.edges())
    h = h + snout
    for s in (1, -1):
        ear = bd.Pos(-6, s * 15, 9) * bd.scale(bd.Sphere(5.0), by=(0.5, 1.3, 0.4))
        h += ear
        h -= bd.Pos(23.2, s * 4.5, -6) * bd.Rot(0, 90, 0) * cyl(1.6, -3, 3)         # nostrils
        h -= bd.Pos(-6, s * 9, 9) * cyl(2.6, 0, 6)                                     # horn sockets
    head_w = _head_frame(h)
    neck = box(72, 92, -11, 11, 84, 110)
    neck = neck.fillet(3.0, neck.edges().filter_by(bd.Axis.X))
    tenon = box(END_X0, 72.5, -5, 5, 90, 100)
    return head_w + neck + tenon


def horn(left: bool) -> bd.Part:
    s = 1 if left else -1
    pts = [(-6, s * 9, 7), (-6, s * 10, 12), (-5, s * 17, 16), (-2, s * 23, 21), (3, s * 25, 28)]
    path = bd.Spline(*[bd.Vector(p) for p in pts])
    radii = [2.5, 2.5, 2.4, 2.0, 1.4, 0.7]
    sections = [path.location_at(i / (len(radii) - 1)) * bd.Circle(r) for i, r in enumerate(radii)]
    h = bd.loft(sections) + path.location_at(1.0) * bd.Sphere(0.7)
    return _head_frame(h)


def eye(left: bool) -> bd.Part:
    s = 1 if left else -1
    return _head_frame(bd.Pos(7, s * 12.6, 4) * bd.Sphere(2.2))


def tail() -> bd.Part:
    """Ø4 hardwood dowel, steamed to shape, glued into the rear plate."""
    path = bd.Spline((-67.0, 0, 96), (-76.0, 0, 95), (-82.0, 0, 84), (-85.0, 0, 70))
    return bd.sweep(path.location_at(0) * bd.Circle(2.0), path)


def tail_tuft() -> bd.Part:
    """Yarn tassel (modelled as its envelope)."""
    tip = bd.Vector(-85.0, 0, 70)
    tuft = bd.scale(bd.Sphere(4.0), by=(0.8, 0.8, 1.8))
    return bd.Pos(tip.X - 0.3, 0, tip.Z - 5.0) * bd.Rot(0, -12, 0) * tuft


