const C = __CONST__;
const LEGS = __LEGS__;
const FRONT = __FRONT__, REAR = __REAR__, BARREL = __BARREL__, GOV = __GOV__, WIND = __WIND__;
const ALL = __ALL__, SEE = __SEE__;

function pose(theta, hip) {
  const t = theta * Math.PI / 180;
  const px = hip + C.r * Math.cos(t), pz = C.az + C.r * Math.sin(t);
  const dx = hip - px, dz = C.gz - pz, d = Math.hypot(dx, dz);
  return { px, pz, ux: dx / d, uz: dz / d, ang: Math.atan2(dz, dx) * 180 / Math.PI };
}
// lowest point of the rocking hoof sole (pad radius hr + pt about its centre)
function foot(p) {
  const c = C.L - C.pt - C.hr;
  return { x: p.px + c * p.ux, z: p.pz + c * p.uz - (C.hr + C.pt) };
